#!/usr/bin/env python3
# ruff: noqa: E501
# Generated by python-toolchain / py-ci-run.
#
# Runs the local quality gate in a fixed order, cheapest first. This file is the
# single definition used by the git pre-commit hook (.pre-commit-config.yaml) and
# by hand, so "the gate" cannot mean two different things.
#
#   uv run python scripts/ci.py --list          # 看计划
#   uv run python scripts/ci.py --stage all     # 跑全部阶段
#   uv run python scripts/ci.py --stage lint,test
#
# 相对插件默认模板改了三处，理由写在 AGENTS.md §6：
#   1. ruff 只查 src tests scripts —— `.tmp_ref/` 是未入库的对标源码，全仓查会报 47 个历史错误；
#   2. pytest 只跑 tests/unit 且不设覆盖率门槛 —— 提交流程要快（<5s），
#      集成层需要真 PG；覆盖率门禁留给后续 CI，不在这里冒充通过；
#   3. `--stage all` **不含 security** —— pip-audit 要联网比对 OSV，
#      放进提交门禁等于让网络抖动决定你能不能提交。security 用 `--stage security`
#      显式跑（本地手动 + CI），不进 pre-commit。
#
# Standard library only: Python 3.11+ on Linux, macOS and Windows.
from __future__ import annotations

import argparse
import contextlib
import json
import os
import subprocess
import sys
import time

PAYLOAD = json.loads(
    r"""{
  "projectName": "pyknora",
  "stages": [
    {
      "id": "lint",
      "title": "Lint",
      "why": "Ruff is fast enough to run on every push, and it is the gate that catches the most mistakes per second spent. `ruff format --check` is separate from `ruff check` on purpose: one is correctness, the other is style, and a single combined step hides which of the two failed.",
      "steps": [
        {
          "id": "ruff-check",
          "label": "ruff check",
          "argv": [
            "uv",
            "run",
            "ruff",
            "check",
            "--output-format=concise",
            "src",
            "tests",
            "scripts"
          ],
          "run": "uv run ruff check --output-format=concise src tests scripts",
          "timeoutSeconds": 900,
          "always": false
        },
        {
          "id": "ruff-format",
          "label": "ruff format --check",
          "argv": [
            "uv",
            "run",
            "ruff",
            "format",
            "--check",
            "src",
            "tests",
            "scripts"
          ],
          "run": "uv run ruff format --check src tests scripts",
          "timeoutSeconds": 900,
          "always": false
        }
      ]
    },
    {
      "id": "test",
      "title": "Test",
      "why": "Tests run after the static gates because a failing test should mean a real regression, not a syntax error the linter would have caught in a tenth of the time.",
      "steps": [
        {
          "id": "pytest",
          "label": "pytest",
          "argv": [
            "uv",
            "run",
            "pytest",
            "-q",
            "tests/unit"
          ],
          "run": "uv run pytest -q tests/unit",
          "timeoutSeconds": 900,
          "always": false
        }
      ]
    }
  ]
}""".replace("\r\n", "\n")
)

STAGES = PAYLOAD["stages"]
PROJECT_NAME = PAYLOAD["projectName"]

# security 单独定义、**不进 `all`**：pip-audit 要联网比对 OSV，结论随远端漏洞库变化，
# 挂到 pre-commit 上等于让网络抖动决定能不能提交。显式 `--stage security`，由人工/CI 跑。
SECURITY_STAGE = {
    "id": "security",
    "title": "Security audit",
    "why": (
        "pip-audit checks the resolved dependency set against OSV. It runs outside the commit "
        "gate because it is the slowest check and the only one whose answer depends on a "
        "remote service."
    ),
    "steps": [
        {
            "id": "pip-audit",
            "label": "pip-audit",
            "argv": ["uv", "run", "--with", "pip-audit", "pip-audit", "--progress-spinner", "off"],
            "run": "uv run --with pip-audit pip-audit --progress-spinner off",
            "timeoutSeconds": 900,
            "always": False,
        }
    ],
}

ALL_STAGES = [*STAGES, SECURITY_STAGE]


def _utf8_stdio() -> None:
    """Windows consoles default to a legacy code page; child output is UTF-8."""
    os.environ.setdefault("PYTHONUTF8", "1")
    os.environ.setdefault("PYTHONIOENCODING", "utf-8")
    for stream in (sys.stdout, sys.stderr):
        reconfigure = getattr(stream, "reconfigure", None)
        if reconfigure is not None:
            with contextlib.suppress(ValueError, OSError):
                reconfigure(encoding="utf-8", errors="replace")


def _select(stage_arg: str) -> list[dict]:
    wanted: list[str] = []
    for part in stage_arg.split(","):
        name = part.strip().lower()
        if not name:
            continue
        if name == "all":
            # `all` 只扩到提交门禁里的阶段；security 必须显式点名。
            wanted.extend(stage["id"] for stage in STAGES)
            continue
        wanted.append(name)
    by_id = {stage["id"]: stage for stage in ALL_STAGES}
    unknown = [name for name in wanted if name not in by_id]
    if unknown:
        known = ", ".join(by_id) or "(none)"
        print(f"unknown stage(s): {', '.join(unknown)}\nknown stages: {known}", file=sys.stderr)
        raise SystemExit(2)
    seen: list[str] = []
    for stage in ALL_STAGES:
        if stage["id"] in wanted and stage["id"] not in seen:
            seen.append(stage["id"])
    return [by_id[name] for name in seen]


def _print_plan(stages: list[dict]) -> None:
    print(f"plan for {PROJECT_NAME}:")
    for index, stage in enumerate(stages, start=1):
        print(f"{index}. {stage['title']} ({stage['id']})")
        for step in stage["steps"]:
            print(f"   $ {step['run']}")


def _venv_executable(name: str, root: str) -> str | None:
    """返回 venv 里的可执行文件路径；找不到返回 None。

    为什么不直接用 `uv run <tool>`：`uv run` 每次都会先初始化 uv 缓存目录
    （本机是 `D:\\uv-cache\\sdists-v9\\.git`），在受限沙箱/权限被改过的机器上
    会直接 `error: Failed to initialize cache ... 拒绝访问 (os error 5)`，
    门禁在第一步就以 exit 2 红掉——那已经不是代码问题，而是环境问题伪装成
    代码问题。venv 里的 exe 是现成的，直连既绕开缓存初始化，也快得多。
    """
    bindir = "Scripts" if os.name == "nt" else "bin"
    suffix = ".exe" if os.name == "nt" else ""
    candidate = os.path.join(root, ".venv", bindir, f"{name}{suffix}")
    return candidate if os.path.isfile(candidate) else None


def _resolve_argv(argv: list[str], root: str) -> list[str]:
    """把 `uv run <tool> ...` 换成 `<venv>/<tool> ...`；解析不到就原样返回。"""
    if len(argv) >= 3 and argv[0] == "uv" and argv[1] == "run" and not argv[2].startswith("-"):
        exe = _venv_executable(argv[2], root)
        if exe is not None:
            return [exe, *argv[3:]]
    return list(argv)


def _run_step(step: dict, root: str, timeout: float) -> tuple[bool, float, int]:
    argv = _resolve_argv(step["argv"], root)
    shown = step["run"] if argv == list(step["argv"]) else subprocess.list2cmdline(argv)
    print(f"\n==> {step['label']}\n    $ {shown}", flush=True)
    started = time.monotonic()
    try:
        completed = subprocess.run(
            argv,
            cwd=root,
            timeout=timeout,
            check=False,
            text=True,
            encoding="utf-8",
            errors="replace",
            shell=False,
        )
        code = completed.returncode
    except FileNotFoundError:
        print(f"    command not found: {step['argv'][0]}", file=sys.stderr)
        code = 127
    except subprocess.TimeoutExpired:
        print(f"    timed out after {timeout:.0f}s", file=sys.stderr)
        code = 124
    elapsed = time.monotonic() - started
    print(f"    -> exit {code} in {elapsed:.1f}s", flush=True)
    return code == 0, elapsed, code


def main(argv: list[str] | None = None) -> int:
    _utf8_stdio()
    parser = argparse.ArgumentParser(description=f"Run the {PROJECT_NAME} quality gates locally.")
    parser.add_argument(
        "--stage",
        default="all",
        help="all (lint,test), or a comma list; security must be named explicitly",
    )
    parser.add_argument(
        "--root", default=".", help="project root to run in (default: this directory)"
    )
    parser.add_argument(
        "--timeout", type=float, default=0, help="per-step seconds; 0 keeps each step's own"
    )
    parser.add_argument("--list", action="store_true", help="print the plan and exit")
    parser.add_argument("--stop-after", default="", help="stop once this stage id has run")
    parser.add_argument("--json", action="store_true", help="machine-readable result on stdout")
    args = parser.parse_args(argv)

    stages = _select(args.stage)
    if args.list:
        _print_plan(stages)
        return 0

    root = os.path.abspath(args.root)
    results: list[dict] = []
    overall = 0
    total = 0.0
    failed = False
    for stage in stages:
        if failed:
            # Nothing new starts once a gate fails: a stage that never began is
            # also never torn down.
            break
        stage_ok = True
        for step in stage["steps"]:
            if not stage_ok and not step.get("always"):
                continue
            timeout = args.timeout if args.timeout > 0 else float(step.get("timeoutSeconds", 900))
            ok, elapsed, code = _run_step(step, root, timeout)
            total += elapsed
            results.append(
                {
                    "stage": stage["id"],
                    "step": step["id"],
                    "ok": ok,
                    "code": code,
                    "seconds": round(elapsed, 1),
                }
            )
            if not ok:
                stage_ok = False
                failed = True
                overall = overall or (code or 1)
        if args.stop_after and stage["id"] == args.stop_after:
            break

    print("\n--- summary ---")
    for item in results:
        mark = "PASS" if item["ok"] else "FAIL"
        print(f"{mark}  {item['stage']}/{item['step']}  {item['seconds']}s")
    print(f"total {total:.1f}s")
    if args.json:
        print(json.dumps({"ok": overall == 0, "results": results, "seconds": round(total, 1)}))
    return overall


if __name__ == "__main__":
    raise SystemExit(main())
